/* Private, outbound-only PC relay. This file never invokes an LLM or operations. */
function ma_fail(string $code, int $status = 400): void { send_json($status, ['error' => $code]); }
function ma_text($v, int $max = 240): string { if (!is_scalar($v) && $v !== null) ma_fail('invalid_schema'); return substr(preg_replace('/[\x00-\x1f<>]/', '', (string)$v), 0, $max); }
function ma_money($v): ?int { return is_int($v) && $v >= 0 && $v <= 1000000000000 ? $v : null; }
function ma_allowed(array $u, string $dbDir): bool {
    $ids = array_filter(explode(',', (string)getenv('FMS_MARKET_AGENT_ALLOWED_USERS')));
    $file = $dbDir . '/market-agent-allowed-users.json';
    if (is_file($file)) { $allowed = json_decode((string)file_get_contents($file), true); $ids = (array)($allowed['userIds'] ?? []); }
    return in_array((string)$u['id'], $ids, true);
}
function ma_context(array $c, array $user): array {
