function ma_result(array $r,array $c): array {
    if(($r['schemaVersion']??0)!==1||!is_array($r['strategy']??null)||!is_array($r['actions']??null)||count($r['actions'])>12)ma_fail('invalid_output');
    $players=[];$market=[];$squad=[];foreach($c['market']as$p){$players[$p['id']]=$p;$market[$p['id']]=true;}foreach($c['squad']as$p){$players[$p['id']]=$p;$squad[$p['id']]=true;}$evidence=array_column($c['evidence'],'id');$seen=[];$sum=0;$actions=[];
    foreach($r['actions']as$a){if(!is_array($a))ma_fail('invalid_output');$type=$a['type']??'';$id=$a['playerId']??null;if(!is_string($id)&&$id!==null)ma_fail('invalid_output');$p=$players[$id]??null;if(!in_array($type,['buy','sell','hold','avoid','wait'],true)||!in_array($a['priority']??0,[1,2,3],true)||!in_array($a['confidence']??'',['low','medium','high'],true)||($type!=='wait'&&!$p)||($id&&isset($seen[$id])))ma_fail('invalid_output');if($id)$seen[$id]=true;if(($type==='buy'&&!isset($market[$id]))||(in_array($type,['sell','hold'],true)&&!isset($squad[$id])))ma_fail('invalid_output');if(!is_array($a['evidenceIds']??null))ma_fail('invalid_output');$refs=$a['evidenceIds'];foreach($refs as$ref)if(!is_string($ref)||!in_array($ref,$evidence,true))ma_fail('invalid_evidence');$amount=null;$max=null;if($type==='buy'){$amount=ma_money($a['amount']??null);$max=ma_money($a['maximumAmount']??null);$f=$c['finance'];$date=strtotime($f['updatedAt']);if(!$date||time()-$date>900||$date>time()+60||$amount===null||$max===null||($f['balance']===null||$f['balance']<0)||$f['availableBudget']===null||$f['maximumBid']===null||$amount>$max||$max>$p['rationalMax']||$max>$f['maximumBid'])ma_fail('invalid_budget');$sum+=max(0,$max-($p['ownBid']??0));}$actions[]=['type'=>$type,'playerId'=>$id,'priority'=>$a['priority'],'confidence'=>$a['confidence'],'reason'=>ma_text($a['reason']??'',500),'evidenceIds'=>array_slice($refs,0,8),'amount'=>$amount,'maximumAmount'=>$max,'prerequisites'=>array_slice(array_map(fn($v)=>ma_text($v),(array)($a['prerequisites']??[])),0,4)];}
    if($sum>($c['finance']['availableBudget']??0))ma_fail('invalid_budget');
    return ['schemaVersion'=>1,'mode'=>'ai','generatedAt'=>gmdate('c'),'strategy'=>['summary'=>ma_text($r['strategy']['summary']??'',700),'priorities'=>array_slice(array_map(fn($v)=>ma_text($v),(array)($r['strategy']['priorities']??[])),0,3)],'actions'=>$actions,'risks'=>array_slice(array_map(fn($v)=>ma_text($v),(array)($r['risks']??[])),0,6),'limitations'=>array_slice(array_map(fn($v)=>ma_text($v),(array)($r['limitations']??[])),0,6)];
}
